binding.script:

  var unit = getprop("/instrumentation/rmu/unit/selected");
  print (unit);
  if (unit == 0 or unit == nil ) {
    var cnlcom = getprop("/yak152/instrumentation/COMM/channel");
    var comm = getprop("/instrumentation/comm/frequencies/standby-mhz");
    setprop("/yak152/instrumentation/COMM/channel-" ~ cnlcom ~ "", comm);
  } elsif (unit == 1 ) {
    var cnladf = getprop("/yak152/instrumentation/ARC-15/channel");
    var adf = getprop("/instrumentation/adf/frequencies/standby-khz");
    setprop("/yak152/instrumentation/ARC-15/channel-" ~ cnladf ~ "", adf);
  } elsif (unit == 2 ) {
    var cnlnav = getprop("/yak152/instrumentation/RSBN/channel");
    var nav = getprop("/instrumentation/nav/frequencies/standby-mhz");
    setprop("yak152/instrumentation/RSBN/channel-" ~ cnlnav ~ "", nav);
  } elsif (unit == 3 ) {
    var cnlnav1 = getprop("/yak152/instrumentation/PRMG/channel");
    var nav1 = getprop("/instrumentation/nav[1]/frequencies/standby-mhz");
    setprop("/yak152/instrumentation/PRMG/channel-" ~ cnlnav1 ~ "", nav1);
  }
